&lt;li&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW191665018 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW191665018 BCX8&quot;&gt;Erfahrung im digitalen Marketingumfeld:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW191665018 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW191665018 BCX8&quot;&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;Du bringst mehrjährige Erfahrung im Performance-, Digital- oder Media-Umfeld mit und hast bereits komplexe Projekte oder Kundenetats erfolgreich gesteuert.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW191665018 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW21389343 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW21389343 BCX8&quot;&gt;Strategisches Verständnis&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW21389343 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW21389343 BCX8&quot;&gt;&lt;strong&gt;: &lt;/strong&gt;Du denkst kanalübergreifend, erkennst Zusammenhänge schnell und kannst strategische Empfehlungen adressatengerecht ableiten und präsentieren.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW235946103 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW235946103 BCX8&quot;&gt;Kommunikationsstärke:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW235946103 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW235946103 BCX8&quot;&gt;&amp;nbsp;Du überzeugst durch ein souveränes Auftreten, starke Präsentationsfähigkeiten und ein hohes Maß an Empathie im Umgang mit&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW235946103 BCX8&quot;&gt;Kund:innen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW235946103 BCX8&quot;&gt;&amp;nbsp;und Teams.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW235946103 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP Selected SCXW21389343 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW263049427 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW263049427 BCX8&quot;&gt;Organisationstalent &amp;amp; Resilienz:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;TextRun SCXW263049427 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW263049427 BCX8&quot;&gt;&amp;nbsp;Auch in dynamischen Projektphasen behältst du den Überblick, priorisierst sicher und arbeitest strukturiert sowie lösungsorientiert.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW263049427 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
