&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Times New Roman&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Times New Roman&amp;quot;,&amp;quot;469769242&amp;quot;:[9642],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;3&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Performance-Analyse:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;‎ Du überwachst und analysierst die&amp;nbsp;TV- und&amp;nbsp;Advanced-TV-Umsätze, sicherst die Datenqualität und kümmerst dich um das tägliche Troubleshooting.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Times New Roman&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Times New Roman&amp;quot;,&amp;quot;469769242&amp;quot;:[9642],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;3&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Finanzielle Steuerung:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;‎ Die Erstellung präziser Prognosen, das Tracking von Umsätzen und die Durchführung von quartalsweisen Abgleichen mit Vermarktern gehören zu deinem Verantwortungsbereich.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Times New Roman&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Times New Roman&amp;quot;,&amp;quot;469769242&amp;quot;:[9642],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;3&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Verhandlungsführung:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;‎ Du bereitest Jahresverhandlungen aktiv vor und führst diese, um optimale Konditionen für unsere Kunden im traditionellen TV und bei Streaming-Formaten zu sichern.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Times New Roman&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Times New Roman&amp;quot;,&amp;quot;469769242&amp;quot;:[9642],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;3&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Partnermanagement:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;‎ Als zentrale Schnittstelle pflegst du den regelmäßigen Austausch mit TV- und CTV/Digital-Vermarktern und&amp;nbsp;führst durch&amp;nbsp;wichtige Termine.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Times New Roman&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Times New Roman&amp;quot;,&amp;quot;469769242&amp;quot;:[9642],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;3&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Vertrags-Compliance:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;‎ Die sorgfältige Prüfung von Rahmenvereinbarungen und die Sicherstellung der korrekten vertraglichen Hinterlegung liegen in deiner Hand.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;469777462&amp;quot;:[360,2160],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
