&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Times New Roman&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Times New Roman&amp;quot;,&amp;quot;469769242&amp;quot;:[9642],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;3&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Kommunikationsfähigkeit:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;‎ Mit verhandlungssicherem Deutsch, fließendem Englisch und einem souveränen Auftreten überzeugst du interne Stakeholder und externe Vermarkter.&lt;/span&gt; &lt;/li&gt;
